    "TurnOffSystemSounds.ps1": "$excludes = Get-ChildItem -LiteralPath 'Registry::HKU\\DefaultUser\\AppEvents\\EventLabels' |\n    Where-Object -FilterScript { ($_ | Get-ItemProperty).ExcludeFromCPL -eq 1; } |\n    Select-Object -ExpandProperty 'PSChildName';\nGet-ChildItem -Path 'Registry::HKU\\DefaultUser\\AppEvents\\Schemes\\Apps\\*\\*' |\n    Where-Object -Property 'PSChildName' -NotIn $excludes |\n    Get-ChildItem -Include '.Current' | Set-ItemProperty -Name '(Default)' -Value '';",
    "UnlockStartLayout.vbs": "HKU = &H80000003\nSet reg = GetObject(\"winmgmts://./root/default:StdRegProv\")\nSet fso = CreateObject(\"Scripting.FileSystemObject\")\n\nIf reg.EnumKey(HKU, \"\", sids) = 0 Then\n\tIf Not IsNull(sids) Then\n\t\tFor Each sid In sids\n\t\t\tkey = sid + \"\\Software\\Policies\\Microsoft\\Windows\\Explorer\"\n\t\t\tname = \"LockedStartLayout\"\n\t\t\tIf reg.GetDWORDValue(HKU, key, name, existing) = 0 Then\n\t\t\t\treg.SetDWORDValue HKU, key, name, 0\n\t\t\tEnd If\n\t\tNext\n\tEnd If\nEnd If",
    "UnlockStartLayout.xml": "<Task version=\"1.2\" xmlns=\"http://schemas.microsoft.com/windows/2004/02/mit/task\">\n\t<Triggers>\n\t\t<EventTrigger>\n\t\t\t<Enabled>true</Enabled>\n\t\t\t<Subscription>&lt;QueryList&gt;&lt;Query Id=\"0\" Path=\"Application\"&gt;&lt;Select Path=\"Application\"&gt;*[System[Provider[@Name='UnattendGenerator'] and EventID=1]]&lt;/Select&gt;&lt;/Query&gt;&lt;/QueryList&gt;</Subscription>\n\t\t</EventTrigger>\n\t</Triggers>\n\t<Principals>\n\t\t<Principal id=\"Author\">\n\t\t\t<UserId>S-1-5-18</UserId>\n\t\t\t<RunLevel>LeastPrivilege</RunLevel>\n\t\t</Principal>\n\t</Principals>\n\t<Settings>\n\t\t<MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>\n\t\t<DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>\n\t\t<StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>\n\t\t<AllowHardTerminate>true</AllowHardTerminate>\n\t\t<StartWhenAvailable>false</StartWhenAvailable>\n\t\t<RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>\n\t\t<IdleSettings>\n\t\t\t<StopOnIdleEnd>true</StopOnIdleEnd>\n\t\t\t<RestartOnIdle>false</RestartOnIdle>\n\t\t</IdleSettings>\n\t\t<AllowStartOnDemand>true</AllowStartOnDemand>\n\t\t<Enabled>true</Enabled>\n\t\t<Hidden>false</Hidden>\n\t\t<RunOnlyIfIdle>false</RunOnlyIfIdle>\n\t\t<WakeToRun>false</WakeToRun>\n\t\t<ExecutionTimeLimit>PT72H</ExecutionTimeLimit>\n\t\t<Priority>7</Priority>\n\t</Settings>\n\t<Actions Context=\"Author\">\n\t\t<Exec>\n\t\t\t<Command>C:\\Windows\\System32\\wscript.exe</Command>\n\t\t\t<Arguments>C:\\Windows\\Setup\\Scripts\\UnlockStartLayout.vbs</Arguments>\n\t\t</Exec>\n\t</Actions>\n</Task>",
